func TestParsePorcelainStatus_TypeChange(t *testing.T) {
	// Type change (symlink → file): "T  link.go\0"
	raw := "T  link.go\x00"
	status := parsePorcelainStatus(raw)

	require.Contains(t, status, "link.go")
